        "TradingSymbol" character varying(128) NOT NULL,
        "PriceStart" double precision,
        "PriceEnd" double precision,
        "PriceChange" double precision,
        "TotalQuantity" bigint NOT NULL,
        "StrictBuy" bigint NOT NULL,
        "StrictSell" bigint NOT NULL,
        "StrictUnknown" bigint NOT NULL,
        "StrictDelta" bigint NOT NULL,
        "EnrichedBuy" bigint NOT NULL,
        "EnrichedSell" bigint NOT NULL,
        "EnrichedUnknown" bigint NOT NULL,
        "EnrichedDelta" bigint NOT NULL,
        "TradeUpdates" bigint NOT NULL,
        "OiStart" bigint,
        "OiEnd" bigint,
        "OiDelta" bigint,
        "IvStart" double precision,
        "IvEnd" double precision,
        "IvChange" double precision,
        "ActivityPerSecond" double precision,
        "QuoteAgeEndSeconds" double precision,
        CONSTRAINT "PK_adaptive_option_strike_bars" PRIMARY KEY ("Id"),
        CONSTRAINT "FK_adaptive_option_strike_bars_adaptive_sessions_SessionId" FOREIGN KEY ("SessionId") REFERENCES adaptive_sessions ("Id") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
